_OUTLINE = ('<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" '
            'stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">%s</svg>')
_SOLID = '<svg class="icon" viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" focusable="false">%s</svg>'


@register.simple_tag
def icon(name):
    if name in BRANDS:
        return mark_safe(_SOLID % ('<path d="%s"/>' % BRANDS[name]))
    return mark_safe(_OUTLINE % ICONS.get(name, ICONS["info"]))
